const US_TERRITORIES = new Set([
  "Puerto Rico", "Guam", "American Samoa", "U.S. Virgin Is.", "N. Mariana Is."
]);

function resolveCountryName(geoName) {
  if (US_TERRITORIES.has(geoName)) return "United States of America";
  if (geoName === "Somaliland") return "Somalia";
  if (geoName === "W. Sahara") return "Morocco";
  return NAME_MAP[geoName] || geoName;
}

function lookupCountry(geoName) {
  const mapped = resolveCountryName(geoName);
  return COUNTRY_DATA.find(c => c.n === mapped || c.n === geoName);
}

const C = {
  navy: "#02569d", navyLight: "#1a6db8", navyDark: "#08477d",
  red: "#fb4147", redDark: "#e0363b",
  white: "#FFFFFF", offWhite: "#F7F8FA",
  g100: "#EEF0F4", g200: "#D8DCE4", g300: "#B0B8C8",
  g400: "#7A859A", g500: "#4A5568",
};

const MAP_COLORS = {
  required: "#fb4147",
  after_time: "#E8884D",
  not_required: "#2D8A56",
  na: "#9CA3AF",
};

function WorldMap({onSelect}) {
  const svgRef = useRef(null);
  const contRef = useRef(null);
  const tipRef = useRef(null);
  const onSelectRef = useRef(onSelect);
  const zoomRef = useRef(null);
  const [geo, setGeo] = useState(null);
  const [dims, setDims] = useState({w:900,h:470});
  const isMobile = dims.w < 600;

  useEffect(() => { onSelectRef.current = onSelect; }, [onSelect]);

  useEffect(() => {
    const obs = new ResizeObserver(e => {
      for (const en of e) {
        const w = en.contentRect.width;
        if (w < 600) {
          setDims({w, h: Math.min(700, w * 1.4)});
        } else {
          setDims({w, h: Math.max(260, w * 0.45)});
        }
      }
    });
    if (contRef.current) obs.observe(contRef.current);
    return () => obs.disconnect();
  }, []);

  useEffect(() => {
    const s = document.createElement("script");
    s.src = "https://cdn.jsdelivr.net/npm/topojson-client@3";
    s.onload = () => {
      fetch("https://cdn.jsdelivr.net/npm/world-atlas@2/countries-50m.json")
        .then(r => r.json()).then(t => setGeo(t)).catch(() => {});
    };
    document.head.appendChild(s);
  }, []);

  const fill = useCallback((name) => {
    const d = lookupCountry(name);
    if (!d || !d.cc) return MAP_COLORS.na;
    return MAP_COLORS[d.cc] || MAP_COLORS.na;
  }, []);

  const tipLabel = useCallback((d) => {
    if (!d) return "Not applicable / Ambiguous";
    if (d.cc === "required") return "Required";
    if (d.cc === "after_time") return "Required after a time";
    if (d.cc === "not_required") return "Not required";
    if (d.cc === "na") {
      if (d.r === "Not Applicable") return "Not Applicable";
      if (d.r === "Ambiguous") return "Ambiguous";
      return "Not applicable / Ambiguous";
    }
    return "Not applicable / Ambiguous";
  }, []);

  useEffect(() => {
    if (!geo || !svgRef.current || !window.topojson) return;
    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();
    const {w, h} = dims;
    const proj = d3.geoNaturalEarth1().fitSize([w, h], {type: "Sphere"});
    const path = d3.geoPath(proj);
    const topojsonLib = window.topojson;

    const allFeatures = topojsonLib.feature(geo, geo.objects.countries).features;

    const somaliaGeoms = geo.objects.countries.geometries.filter(g =>
      g.properties.name === "Somalia" || g.properties.name === "Somaliland"
    );
    const mergedSomaliaGeo = topojsonLib.merge(geo, somaliaGeoms);

    const countryGroups = {};
    const features = [];

    allFeatures.forEach(f => {
      const geoName = f.properties.name;
      if (geoName === "Somalia" || geoName === "Somaliland") return;
      features.push(f);
    });

    const mergedSomaliaFeature = {
      type: "Feature",
      properties: { name: "Somalia" },
      geometry: mergedSomaliaGeo
    };
    features.push(mergedSomaliaFeature);

    features.forEach((f, i) => {
      const resolved = resolveCountryName(f.properties.name);
      if (!countryGroups[resolved]) countryGroups[resolved] = [];
      countryGroups[resolved].push(i);
    });

    const g = svg.append("g");

    g.append("path").datum({type:"Sphere"}).attr("d",path).attr("fill","#F0F3F8").attr("stroke","#D0D5DD").attr("stroke-width",0.5);
    g.append("path").datum(d3.geoGraticule10()).attr("d",path).attr("fill","none").attr("stroke","#E2E6EC").attr("stroke-width",0.3).attr("class","graticule");

    const countryPaths = g.selectAll("path.c").data(features).join("path").attr("class","c")
      .attr("d", path)
      .attr("fill", d => fill(d.properties.name))
      .attr("stroke", "none")
      .style("cursor","pointer");

    const interiorBorders = topojsonLib.mesh(geo, geo.objects.countries, (a, b) => {
      const na = a.properties.name;
      const nb = b.properties.name;
      if ((na === "Somalia" && nb === "Somaliland") || (na === "Somaliland" && nb === "Somalia")) return false;
      return a !== b;
    });
    const borderPath = g.append("path")
      .datum(interiorBorders)
      .attr("d", path)
      .attr("fill", "none")
      .attr("stroke", "#fff")
      .attr("stroke-width", 0.5)
      .attr("stroke-linejoin", "round")
      .attr("class", "borders")
      .style("pointer-events", "none");

    const outerBorder = topojsonLib.mesh(geo, geo.objects.countries, (a, b) => a === b);
    const outerPath = g.append("path")
      .datum(outerBorder)
      .attr("d", path)
      .attr("fill", "none")
      .attr("stroke", "#fff")
      .attr("stroke-width", 0.5)
      .attr("stroke-linejoin", "round")
      .attr("class", "outer-borders")
      .style("pointer-events", "none");

    const highlightLayer = g.append("g").attr("class", "highlight-layer").style("pointer-events", "none");

    // Pre-compute merged geometries and path strings for each country group
    const precomputedHighlights = {};
    const geomsByResolved = {};
    geo.objects.countries.geometries.forEach(geom => {
      const resolved = resolveCountryName(geom.properties.name);
      if (!geomsByResolved[resolved]) geomsByResolved[resolved] = [];
      geomsByResolved[resolved].push(geom);
    });
    Object.keys(countryGroups).forEach(resolved => {
      const geoms = geomsByResolved[resolved];
      if (geoms && geoms.length > 0) {
        const merged = topojsonLib.merge(geo, geoms);
        precomputedHighlights[resolved] = path(merged);
      }
    });

    const tipEl = tipRef.current;
    const showTip = (name, label, x, y) => {
      if (!tipEl) return;
      tipEl.children[0].textContent = name;
      tipEl.children[1].textContent = label;
      tipEl.style.left = (x + 12) + "px";
      tipEl.style.top = (y - 40) + "px";
      tipEl.style.display = "block";
    };
    const hideTip = () => { if (tipEl) tipEl.style.display = "none"; };

    const hasHover = window.matchMedia("(hover: hover)").matches;

    const interactionPaths = g.selectAll("path.interact").data(features).join("path").attr("class","interact")
      .attr("d", path)
      .attr("fill", "transparent")
      .attr("stroke", "none")
      .style("cursor","pointer");

    if (hasHover) {
      interactionPaths
        .on("mouseenter", function(ev, d) {
          const geoName = d.properties.name;
          const resolved = resolveCountryName(geoName);
          const groupIndices = countryGroups[resolved] || [];

          groupIndices.forEach(idx => {
            countryPaths.nodes()[idx].setAttribute("opacity", "0.8");
          });

          highlightLayer.selectAll("*").remove();
          const pathD = precomputedHighlights[resolved];
          if (pathD) {
            const currentK = currentZoomK.k || 1;
            highlightLayer.append("path")
              .attr("d", pathD)
              .attr("fill", "none")
              .attr("stroke", C.navy)
              .attr("stroke-width", 1.5 / currentK)
              .attr("stroke-linejoin", "round");
          }

          const dt = lookupCountry(geoName);
          const r = contRef.current.getBoundingClientRect();
          showTip(dt ? dt.n : (resolved || geoName), tipLabel(dt), ev.clientX - r.left, ev.clientY - r.top);
        })
        .on("mousemove", function(ev) {
          const r = contRef.current.getBoundingClientRect();
          const tipEl = tipRef.current;
          if (tipEl && tipEl.style.display !== "none") {
            tipEl.style.left = (ev.clientX - r.left + 12) + "px";
            tipEl.style.top = (ev.clientY - r.top - 40) + "px";
          }
        })
        .on("mouseleave", function(ev, d) {
          const geoName = d.properties.name;
          const resolved = resolveCountryName(geoName);
          const groupIndices = countryGroups[resolved] || [];
          groupIndices.forEach(idx => {
            countryPaths.nodes()[idx].setAttribute("opacity", "1");
          });
          highlightLayer.selectAll("*").remove();
          hideTip();
        });
    }

    interactionPaths.on("click", function(ev, d) {
      ev.stopPropagation();
      const dt = lookupCountry(d.properties.name);
      if (dt) onSelectRef.current(dt);
    });

    const currentZoomK = { k: 1 };

    const mob = w < 600;
    const mobileMinScale = mob ? 2 : 1;
    const pad = mob ? 0.25 : 0.3;
    const zoom = d3.zoom().scaleExtent([mobileMinScale,32])
      .translateExtent([[-(w*pad),-(h*pad)],[w*(1+pad),h*(1+pad)]])
      .filter(ev => {
        if (ev.type === "wheel") return false;
        return !ev.button;
      })
      .on("zoom", ev => {
        g.attr("transform", ev.transform);
        const k = ev.transform.k;
        currentZoomK.k = k;
        borderPath.attr("stroke-width", 0.5 / k);
        outerPath.attr("stroke-width", 0.5 / k);
        g.select(".graticule").attr("stroke-width", 0.3 / k);
        g.select("path:first-child").attr("stroke-width", 0.5 / k);
        highlightLayer.selectAll("path").attr("stroke-width", 1.5 / k);
      });
    svg.call(zoom);
    if (w < 600) {
      const initScale = 3;
      const algeriaX = w * 0.48;
      const algeriaY = h * 0.52;
      const initX = w / 2 - algeriaX * initScale;
      const initY = h / 2 - algeriaY * initScale;
      const t = d3.zoomIdentity.translate(initX, initY).scale(initScale);
      svg.call(zoom.transform, t);
    }
    zoomRef.current = { zoom, svg };
  }, [geo, dims, fill, tipLabel]);

  return (
    <div ref={contRef} style={{position:"relative",width:"100%",background:"#F0F3F8",borderRadius:12,overflow:"hidden",border:`1px solid ${C.g200}`}}>
      {!geo && <div style={{display:"flex",alignItems:"center",justifyContent:"center",height:400,fontFamily:"'DM Sans',sans-serif",color:C.g400}}>
        <div style={{textAlign:"center"}}><div style={{fontSize:32,marginBottom:12}}>{"\ud83c\udf0d"}</div>Loading map data...</div>
      </div>}
      <svg ref={svgRef} width={dims.w} height={dims.h} style={{display:geo?"block":"none"}} />
      {geo && <div style={{position:"absolute",top:12,right:12,display:"flex",flexDirection:"column",gap:4,zIndex:10}}>
        <button onClick={() => { if (zoomRef.current) { const {zoom,svg} = zoomRef.current; svg.transition().duration(300).call(zoom.scaleBy, 2); }}}
          style={{width:36,height:36,borderRadius:8,border:"none",background:"rgba(255,255,255,0.92)",color:C.navy,fontSize:20,fontWeight:700,cursor:"pointer",boxShadow:"0 2px 8px rgba(0,0,0,0.1)",display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'DM Sans',sans-serif"}}>+</button>
        <button onClick={() => { if (zoomRef.current) { const {zoom,svg} = zoomRef.current; svg.transition().duration(300).call(zoom.scaleBy, 0.5); }}}
          style={{width:36,height:36,borderRadius:8,border:"none",background:"rgba(255,255,255,0.92)",color:C.navy,fontSize:20,fontWeight:700,cursor:"pointer",boxShadow:"0 2px 8px rgba(0,0,0,0.1)",display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'DM Sans',sans-serif"}}>{"\u2212"}</button>
      </div>}
      <div ref={tipRef} style={{position:"absolute",display:"none",background:C.navyDark,color:C.white,padding:"8px 14px",borderRadius:8,fontFamily:"'DM Sans',sans-serif",fontSize:13,pointerEvents:"none",zIndex:10,boxShadow:"0 4px 16px rgba(0,0,0,0.2)",whiteSpace:"nowrap"}}>
        <div style={{fontWeight:700,marginBottom:2}}></div>
        <div style={{fontSize:11,color:C.g300}}></div>
      </div>
      {geo && <div className="map-legend" style={{position:"absolute",bottom:12,left:12,background:"rgba(255,255,255,0.92)",borderRadius:8,padding:"10px 14px",fontSize:11,fontFamily:"'DM Sans',sans-serif",color:C.g500,boxShadow:"0 2px 8px rgba(0,0,0,0.08)"}}>
        <div style={{fontWeight:700,marginBottom:6,fontSize:11,color:C.navy}}>IDP Requirement</div>
        {[{c:MAP_COLORS.required,l:"Required*"},{c:MAP_COLORS.after_time,l:"Required after a time"},{c:MAP_COLORS.not_required,l:"Not required"},{c:MAP_COLORS.na,l:"Not applicable / Ambiguous"}].map(x =>
          <div key={x.l} style={{display:"flex",alignItems:"center",gap:6,marginBottom:3}}><div style={{width:12,height:12,borderRadius:3,background:x.c,flexShrink:0}} /><span>{x.l}</span></div>
        )}
        <div className="legend-note" style={{marginTop:5,fontSize:9.5,color:C.g400,lineHeight:1.5,maxWidth:260}}>*Includes countries accepting official license translations or an IDP</div>
        <div className="legend-click-hint" style={{marginTop:5,fontSize:10,color:C.g400}}>Click country for details</div>
      </div>}
    </div>
  );
}

function Detail({c, onClose}) {
  if (!c) return null;
  const catColor = cc => {
    if (cc === "required") return MAP_COLORS.required;
    if (cc === "after_time") return MAP_COLORS.after_time;
    if (cc === "not_required") return MAP_COLORS.not_required;
    return MAP_COLORS.na;
  };
  const reqLabel = (raw, cc) => {
    if (cc === "required") {
      if (raw === "Yes, or official translation") return "Required (or official translation)";
      return "Required";
    }
    if (cc === "after_time") return "Required after a time";
    if (cc === "not_required") return "Not required";
    if (raw === "Not Applicable") return "Not Applicable";
    if (raw === "Ambiguous") return "Ambiguous";
    return "Not applicable / Ambiguous";
  };
  const ec = e => {if(e==="High") return C.red; if(e==="Medium") return "#D97706"; if(e==="Low") return "#2D8A56"; return C.g400;};
  const hp = c.p && c.p !== "NA" && c.p !== "" && c.p !== "Unknown";
  const reqColor = catColor(c.cc);
  return (
    <>
      <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.35)",zIndex:90,cursor:"pointer"}} />
      <div style={{position:"fixed",left:window.innerWidth < 600 ? 24 : 12,right:window.innerWidth < 600 ? 24 : 12,zIndex:100,background:C.white,borderRadius:16,border:`3px solid ${C.navy}`,boxShadow:"0 -8px 40px rgba(0,0,0,0.15)",overflowY:"auto",WebkitOverflowScrolling:"touch",animation:"slideUp 0.3s ease-out",...(window.innerWidth < 600 ? {top:12,bottom:12} : {bottom:12,maxHeight:"85vh"})}}>
        <div style={{position:"sticky",top:0,background:C.white,borderRadius:"13px 13px 0 0",padding:"12px 24px 0",zIndex:2}}>
          <div style={{width:40,height:4,background:C.g200,borderRadius:2,margin:"0 auto 12px"}} />
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
            <h3 style={{fontFamily:"'Figtree',sans-serif",fontSize:"clamp(20px, 3vw, 26px)",fontWeight:700,color:C.navy,margin:0}}>{c.n}</h3>
            <button onClick={onClose} style={{background:C.offWhite,border:"none",width:36,height:36,borderRadius:"50%",fontSize:18,color:C.g400,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{"\u2715"}</button>
          </div>
        </div>
        <div style={{padding:"0 24px 24px"}}>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(200px,1fr))",gap:12,marginBottom:16}}>
            <div style={{padding:"14px 18px",background:`${reqColor}08`,borderRadius:10,border:`1px solid ${reqColor}20`}}>
              <div style={{fontFamily:"'DM Sans',sans-serif",fontSize:12,fontWeight:600,textTransform:"uppercase",letterSpacing:"0.1em",color:C.g400,marginBottom:6}}>IDP Requirement</div>
              <div style={{fontFamily:"'DM Sans',sans-serif",fontSize:15,fontWeight:700,color:reqColor,marginBottom:c.rd?8:0}}>{reqLabel(c.r, c.cc)}</div>
              {c.rd && <div style={{fontFamily:"'DM Sans',sans-serif",fontSize:13,color:C.g500,lineHeight:1.6}}>{c.rd}</div>}
              {c.src && <div style={{marginTop:8}}><a href={c.src} target="_blank" rel="noopener noreferrer" style={{fontFamily:"'DM Sans',sans-serif",fontSize:12,color:C.navyLight,textDecoration:"none",borderBottom:`1px solid ${C.navyLight}40`}}>Source: {c.srcLabel || new URL(c.src).hostname}</a></div>}
            </div>
            <div style={{padding:"14px 18px",background:`${ec(c.e)}08`,borderRadius:10,border:`1px solid ${ec(c.e)}20`}}>
              <div style={{fontFamily:"'DM Sans',sans-serif",fontSize:12,fontWeight:600,textTransform:"uppercase",letterSpacing:"0.1em",color:C.g400,marginBottom:6}}>IDP Enforcement</div>
              <div style={{fontFamily:"'DM Sans',sans-serif",fontSize:15,fontWeight:700,color:ec(c.e),marginBottom:c.ed?8:0}}>{c.e || "No data"}</div>
              {c.ed && <div style={{fontFamily:"'DM Sans',sans-serif",fontSize:13,color:C.g500,lineHeight:1.6}}>{c.ed}</div>}
            </div>
            <div style={{padding:"14px 18px",background:C.offWhite,borderRadius:10,border:`1px solid ${C.g200}`}}>
              <div style={{fontFamily:"'DM Sans',sans-serif",fontSize:12,fontWeight:600,textTransform:"uppercase",letterSpacing:"0.1em",color:C.g400,marginBottom:6}}>Consequences of Driving without an IDP</div>
              <div style={{fontFamily:"'DM Sans',sans-serif",fontSize:15,fontWeight:700,color:hp?C.navy:C.g400,marginBottom:c.pd?8:0}}>{hp ? c.p : "Not specified"}</div>
              {c.pd && <div style={{fontFamily:"'DM Sans',sans-serif",fontSize:13,color:C.g500,lineHeight:1.6}}>{c.pd}</div>}
            </div>
          </div>
          {c.s && <div style={{padding:14,background:C.offWhite,borderRadius:8,borderLeft:`3px solid ${C.navy}`}}>
            <div style={{fontFamily:"'DM Sans',sans-serif",fontSize:12,fontWeight:600,textTransform:"uppercase",letterSpacing:"0.1em",color:C.g400,marginBottom:6}}>Summary</div>
            <p style={{fontFamily:"'DM Sans',sans-serif",fontSize:14,color:C.g500,lineHeight:1.75,margin:0}}>{c.s}</p>
          </div>}
        </div>
      </div>
    </>
  );
}

function MapPage() {
  const [q, setQ] = useState("");
  const [sel, setSel] = useState(null);
  const filt = q.length > 0 ? COUNTRY_DATA.filter(c => c.n.toLowerCase().includes(q.toLowerCase())) : [];
  const pick = c => { setSel(c); setQ(""); };

  const searchColor = cc => {
    if (cc === "required") return MAP_COLORS.required;
    if (cc === "after_time") return MAP_COLORS.after_time;
    if (cc === "not_required") return MAP_COLORS.not_required;
    return MAP_COLORS.na;
  };
  const searchLabel = cc => {
    if (cc === "required") return "Required";
    if (cc === "after_time") return "After a time";
    if (cc === "not_required") return "Not required";
    return "N/A / Ambiguous";
  };

  return (
    <div style={{width:"100vw",minHeight:"100vh",display:"flex",flexDirection:"column",overflow:window.innerWidth < 600 ? "auto" : "hidden"}}>
      <section style={{padding:"12px clamp(12px, 3vw, 24px) 24px",background:C.white,flex:window.innerWidth < 600 ? "none" : 1,overflow:window.innerWidth < 600 ? "visible" : "hidden"}}>
        <div style={{maxWidth:1200,margin:"0 auto",height:"100%"}}>
          <div style={{maxWidth:600,margin:"0 auto 16px",position:"relative",zIndex:20}}>
            <div style={{position:"relative"}}>
              <div style={{position:"absolute",left:20,top:"50%",transform:"translateY(-50%)",fontSize:18,color:C.g400}}>{"\ud83d\udd0d"}</div>
              <input type="text" placeholder="Search for a country..." value={q} onChange={e => setQ(e.target.value)}
                onKeyDown={e => { if (e.key === "Enter" && filt.length > 0) { pick(filt[0]); } }}
                style={{width:"100%",padding:"14px 20px 14px 52px",borderRadius:12,border:`2px solid ${C.g200}`,fontFamily:"'DM Sans',sans-serif",fontSize:15,color:C.navy,outline:"none",transition:"border-color 0.2s",boxSizing:"border-box"}}
                onFocus={e => e.target.style.borderColor = C.navy}
                onBlur={e => setTimeout(() => e.target.style.borderColor = C.g200, 200)} />
            </div>
            {q.length > 0 && filt.length > 0 && (
              <div style={{position:"absolute",top:"100%",left:0,right:0,background:C.white,borderRadius:"0 0 12px 12px",border:`1px solid ${C.g200}`,borderTop:"none",maxHeight:320,overflowY:"auto",boxShadow:"0 8px 32px rgba(0,0,0,0.1)"}}>
                {filt.slice(0,15).map((c, i) => {
                  const col = searchColor(c.cc);
                  return (
                    <button key={i} onClick={() => pick(c)}
                      style={{display:"flex",justifyContent:"space-between",alignItems:"center",width:"100%",padding:"14px 20px",background:"none",border:"none",borderBottom:i < Math.min(filt.length,15)-1 ? `1px solid ${C.g100}` : "none",cursor:"pointer",fontFamily:"'DM Sans',sans-serif",fontSize:14.5,color:C.navy,textAlign:"left"}}
                      onMouseEnter={e => e.currentTarget.style.background = C.offWhite}
                      onMouseLeave={e => e.currentTarget.style.background = "none"}>
                      <span style={{fontWeight:600}}>{c.n}</span>
                      <span style={{fontSize:12,fontWeight:600,color:col,background:col+"12",padding:"3px 10px",borderRadius:100}}>{searchLabel(c.cc)}</span>
                    </button>
                  );
                })}
                {filt.length > 15 && <div style={{padding:"10px 20px",fontSize:12,color:C.g400,textAlign:"center"}}>+{filt.length - 15} more</div>}
              </div>
            )}
            {q.length > 0 && filt.length === 0 && (
              <div style={{position:"absolute",top:"100%",left:0,right:0,background:C.white,borderRadius:"0 0 12px 12px",border:`1px solid ${C.g200}`,borderTop:"none",padding:20,textAlign:"center",color:C.g400,fontFamily:"'DM Sans',sans-serif",fontSize:14}}>No countries found</div>
            )}
          </div>
          <WorldMap onSelect={pick} />
        </div>
      </section>
      {sel && <Detail c={sel} onClose={() => setSel(null)} />}
    </div>
  );
}

export default function App() {
  return <MapPage />;
}
